"""
Comprehensive test for the fix to ensure it handles various scenarios
"""

from dataclasses import dataclass, field
from typing import List, Optional
from mashumaro.config import BaseConfig
from mashumaro.jsonschema import build_json_schema
import json

# Test 1: Original issue - third party class with serialization strategy
def as_str(value) -> str:
    return str(value)

class Bar:
    def __init__(self, value="default"):
        self.value = value

    def __str__(self):
        return f"Bar({self.value})"

@dataclass
class Foo:
    bar: Bar = field(default_factory=lambda: Bar("test"))

    class Config(BaseConfig):
        serialization_strategy = {
            Bar: {
                "serialize": as_str,
                "deserialize": Bar,
            }
        }

# Test 2: Regular types with defaults (should still work)
@dataclass
class RegularTypes:
    integer_field: int = 42
    string_field: str = "hello"
    list_field: List[int] = field(default_factory=lambda: [1, 2, 3])

# Test 3: Optional field with third party default
@dataclass
class OptionalThirdParty:
    maybe_bar: Optional[Bar] = None

    class Config(BaseConfig):
        serialization_strategy = {
            Bar: {
                "serialize": as_str,
                "deserialize": Bar,
            }
        }

# Test 4: No serialization strategy (should fall back to original behavior)
class Baz:
    pass

@dataclass
class NoStrategy:
    baz: Baz = field(default_factory=Baz)

if __name__ == "__main__":
    print("=== Test 1: Third party with serialization strategy ===")
    try:
        schema = build_json_schema(Foo)
        print("Success!")
        result = json.loads(schema.to_json())
        print(json.dumps(result, indent=2))
        # Check that the default is serialized as string
        assert result["properties"]["bar"]["type"] == "string"
        assert "Bar(test)" in result["properties"]["bar"]["default"]
    except Exception as e:
        print(f"Error: {type(e).__name__}: {e}")
        import traceback
        traceback.print_exc()

    print("\n=== Test 2: Regular types with defaults ===")
    try:
        schema = build_json_schema(RegularTypes)
        print("Success!")
        result = json.loads(schema.to_json())
        print(json.dumps(result, indent=2))
        # Check defaults are preserved
        assert result["properties"]["integer_field"]["default"] == 42
        assert result["properties"]["string_field"]["default"] == "hello"
        assert result["properties"]["list_field"]["default"] == [1, 2, 3]
    except Exception as e:
        print(f"Error: {type(e).__name__}: {e}")
        import traceback
        traceback.print_exc()

    print("\n=== Test 3: Optional third party field ===")
