        schema = build_json_schema(OptionalThirdParty)
        print("Success!")
        result = json.loads(schema.to_json())
        print(json.dumps(result, indent=2))
        # Should work even though default is None
    except Exception as e:
        print(f"Error: {type(e).__name__}: {e}")
        import traceback
        traceback.print_exc()

    print("\n=== Test 4: No serialization strategy ===")
    try:
        schema = build_json_schema(NoStrategy)
        print("Success!")
        result = json.loads(schema.to_json())
        print(json.dumps(result, indent=2))
    except Exception as e:
        print(f"Error: {type(e).__name__}: {e}")
        # This might fail as expected since Baz is not serializable
